create table public.inventarios_fisicos(id uuid primary key default gen_random_uuid(),location_id uuid not null references public.locations(id),estado text not null default 'abierto' check(estado in('abierto','cerrado','cancelado')),creado_por uuid not null references public.staff(id),cerrado_por uuid references public.staff(id),fecha_inicio timestamptz not null default now(),fecha_cierre timestamptz,observacion text);
create table public.inventario_fisico_items(id uuid primary key default gen_random_uuid(),inventario_id uuid not null references public.inventarios_fisicos(id) on delete cascade,variant_id uuid not null references public.product_variants(id),cantidad_sistema integer not null,cantidad_contada integer,diferencia integer generated always as (case when cantidad_contada is null then null else cantidad_contada-cantidad_sistema end) stored,unique(inventario_id,variant_id));
alter table public.inventarios_fisicos enable row level security;alter table public.inventario_fisico_items enable row level security;
create policy invfis_read on public.inventarios_fisicos for select to authenticated using(private.auth_is_admin() or location_id=private.auth_location_id());
create policy invfis_items_read on public.inventario_fisico_items for select to authenticated using(exists(select 1 from public.inventarios_fisicos f where f.id=inventario_id and(private.auth_is_admin() or f.location_id=private.auth_location_id())));
create or replace function public.iniciar_inventario_fisico(p_observacion text default null) returns public.inventarios_fisicos language plpgsql security definer set search_path='public','private' as $$declare s public.staff;f public.inventarios_fisicos;begin select * into s from public.staff where user_id=auth.uid() and activo=true limit 1;if s.id is null or not(s.rol='administrador' or s.puesto in('tecnico','encargado','jefa')) then raise exception 'Sin permiso';end if;if exists(select 1 from public.inventarios_fisicos where location_id=s.location_id and estado='abierto') then raise exception 'Ya existe un conteo abierto';end if;insert into public.inventarios_fisicos(location_id,creado_por,observacion) values(s.location_id,s.id,nullif(btrim(p_observacion),'')) returning * into f;insert into public.inventario_fisico_items(inventario_id,variant_id,cantidad_sistema) select f.id,i.variant_id,i.cantidad from public.inventory i where i.location_id=s.location_id;return f;end$$;
create or replace function public.registrar_conteo_fisico(p_inventario_id uuid,p_variant_id uuid,p_cantidad integer) returns boolean language plpgsql security definer set search_path='public','private' as $$declare s public.staff;f public.inventarios_fisicos;begin select * into s from public.staff where user_id=auth.uid() and activo=true limit 1;if s.id is null or not(s.rol='administrador' or s.puesto in('tecnico','encargado','jefa')) then raise exception 'Sin permiso';end if;if p_cantidad<0 then raise exception 'Cantidad inválida';end if;select * into f from public.inventarios_fisicos where id=p_inventario_id;if f.id is null or f.location_id<>s.location_id or f.estado<>'abierto' then raise exception 'Conteo no editable';end if;update public.inventario_fisico_items set cantidad_contada=p_cantidad where inventario_id=f.id and variant_id=p_variant_id;if not found then insert into public.inventario_fisico_items(inventario_id,variant_id,cantidad_sistema,cantidad_contada) values(f.id,p_variant_id,0,p_cantidad);end if;return true;end$$;
create or replace function public.cerrar_inventario_fisico(p_inventario_id uuid) returns public.inventarios_fisicos language plpgsql security definer set search_path='public','private' as $$declare s public.staff;f public.inventarios_fisicos;i public.inventario_fisico_items;begin select * into s from public.staff where user_id=auth.uid() and activo=true limit 1;if s.id is null or not(s.rol='administrador' or s.puesto in('encargado','jefa')) then raise exception 'Solo administración/encargado puede cerrar conteo';end if;select * into f from public.inventarios_fisicos where id=p_inventario_id for update;if f.id is null or f.location_id<>s.location_id or f.estado<>'abierto' then raise exception 'Conteo no cerrable';end if;if exists(select 1 from public.inventario_fisico_items where inventario_id=f.id and cantidad_contada is null) then raise exception 'Faltan productos por contar';end if;for i in select * from public.inventario_fisico_items where inventario_id=f.id and diferencia<>0 loop insert into public.inventory(variant_id,location_id,cantidad) values(i.variant_id,f.location_id,i.cantidad_contada) on conflict(variant_id,location_id) do update set cantidad=excluded.cantidad,updated_at=now();insert into public.inventory_movements(variant_id,location_id,cantidad_delta,motivo,staff_id) values(i.variant_id,f.location_id,i.diferencia,'Ajuste conteo físico',s.id);end loop;update public.inventarios_fisicos set estado='cerrado',cerrado_por=s.id,fecha_cierre=now() where id=f.id returning * into f;return f;end$$;
grant execute on function public.iniciar_inventario_fisico(text) to authenticated;grant execute on function public.registrar_conteo_fisico(uuid,uuid,integer) to authenticated;grant execute on function public.cerrar_inventario_fisico(uuid) to authenticated;
create trigger audit_inventarios_fisicos after insert or update or delete on public.inventarios_fisicos for each row execute function private.registrar_auditoria();